DROP TABLE IF EXISTS `absensi_peserta`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `absensi_peserta` (
  `id` int NOT NULL AUTO_INCREMENT,
  `username` varchar(50) COLLATE utf8mb4_general_ci NOT NULL,
  `tanggal` date NOT NULL,
  `jam_masuk` time DEFAULT NULL,
  `jam_keluar` time DEFAULT NULL,
  `status` enum('Hadir','Izin','Sakit','Alpha') COLLATE utf8mb4_general_ci DEFAULT 'Hadir',
  `keterangan` text COLLATE utf8mb4_general_ci,
  `file_surat` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `lat_masuk` decimal(10,8) DEFAULT NULL,
  `lng_masuk` decimal(11,8) DEFAULT NULL,
  `lat_keluar` decimal(10,8) DEFAULT NULL,
  `lng_keluar` decimal(11,8) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `approval_status` enum('Pending','Disetujui','Ditolak') COLLATE utf8mb4_general_ci DEFAULT 'Disetujui',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unik_absensi` (`username`,`tanggal`),
  KEY `idx_username` (`username`),
  KEY `idx_tanggal` (`tanggal`)
) ENGINE=InnoDB AUTO_INCREMENT=8610 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
