--
-- Table structure for table `laporan_magang`
--

DROP TABLE IF EXISTS `laporan_magang`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `laporan_magang` (
  `id` int NOT NULL AUTO_INCREMENT,
  `username` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT 'merujuk ke kolom username pada tabel users/peserta',
  `file_laporan` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `nama_file` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `ukuran_file` int NOT NULL COMMENT 'dalam bytes',
  `sdm_status` enum('Menunggu','Disetujui','Ditolak') COLLATE utf8mb4_general_ci DEFAULT 'Menunggu',
  `sdm_reviewed_by` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sdm_tgl_review` datetime DEFAULT NULL,
  `sdm_keterangan_tolak` text COLLATE utf8mb4_general_ci,
  `manager_status` enum('Menunggu','Disetujui','Ditolak') COLLATE utf8mb4_general_ci DEFAULT 'Menunggu',
  `manager_reviewed_by` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `manager_tgl_review` datetime DEFAULT NULL,
  `manager_keterangan_tolak` text COLLATE utf8mb4_general_ci,
  `status` enum('Menunggu','Disetujui','Ditolak','Menunggu Manager') COLLATE utf8mb4_general_ci DEFAULT 'Menunggu',
  `keterangan_tolak` text COLLATE utf8mb4_general_ci COMMENT 'diisi pusat jika ditolak',
  `tgl_upload` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `tgl_review` timestamp NULL DEFAULT NULL,
  `reviewed_by` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'username user pusat yang mereview',
  PRIMARY KEY (`id`),
  KEY `username` (`username`),
  CONSTRAINT `fk_laporan_username` FOREIGN KEY (`username`) REFERENCES `peserta` (`username`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=376 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `laporan_magang`
--

LOCK TABLES `laporan_magang` WRITE;
