--
-- Table structure for table `sertifikat_magang`
--

DROP TABLE IF EXISTS `sertifikat_magang`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sertifikat_magang` (
  `id` int NOT NULL AUTO_INCREMENT,
  `username` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT 'merujuk ke username peserta',
  `laporan_id` int NOT NULL COMMENT 'merujuk ke id laporan_magang yang disetujui',
  `nomor_surat` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT 'nomor surat sertifikat',
  `qr_token` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `file_sertifikat` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'file sertifikat scan (PDF/JPG) dari pusat',
  `digital_file` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `nama_file_scan` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `ukuran_file_scan` int DEFAULT NULL COMMENT 'dalam bytes',
  `status` enum('Belum Upload','Sudah Upload','Digital') COLLATE utf8mb4_general_ci DEFAULT 'Belum Upload',
  `tgl_cetak` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'tanggal cetak sertifikat pertama kali',
  `tgl_upload_scan` timestamp NULL DEFAULT NULL COMMENT 'tanggal upload sertifikat scan',
  `manager_approved_at` datetime DEFAULT NULL,
  `generated_at` datetime DEFAULT NULL,
  `uploaded_by` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'username user pusat yang upload scan',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_username` (`username`),
  KEY `fk_laporan` (`laporan_id`)
) ENGINE=InnoDB AUTO_INCREMENT=315 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Menyimpan data sertifikat magang peserta';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `sertifikat_magang`
--

LOCK TABLES `sertifikat_magang` WRITE;
/*!40000 ALTER TABLE `sertifikat_magang` DISABLE KEYS */;
